let packetEnumMap = null;

let l2l1_logCntWarnExtPoints;

let l2l1_detectedMsgIds = [];

let l2l1_ptr = null;
/* @type {DataView} */
let l2l1_dv = null;

let l2l1_error_flag = false;
const l2l1_isLittleEndian = true;

function l2l1_getU8( offset ) {
    return l2l1_dv.getUint8( offset );
}

function l2l1_getU16( offset ) {
    return l2l1_dv.getUint16( offset, l2l1_isLittleEndian );

}

function l2l1_getU32( offset ) {
    return l2l1_dv.getUint32( offset, l2l1_isLittleEndian );

}

function l2l1_getU64( offset ) {
    return l2l1_dv.getBigUint64( offset, l2l1_isLittleEndian );
}

function l2l1_getI8( offset ) {
    return l2l1_dv.getInt8( offset );

}

function l2l1_getI16( offset ) {
    return l2l1_dv.getInt16( offset, l2l1_isLittleEndian );

}

function l2l1_getI32( offset ) {
    return l2l1_dv.getInt32( offset, l2l1_isLittleEndian );

}

function l2l1_getI64( offset ) {
    return l2l1_dv.getBigInt64( offset, l2l1_isLittleEndian );
}

function l2l1_getF32( offset ) {
    return l2l1_dv.getFloat32( offset, l2l1_isLittleEndian );
}

function l2l1_getU8Array( offset, count ) {
    if(l2l1_ptr.length <= offset + count-1) throw new Error("Offset is out of bounds!");
    let arr = [];
    for( let i = 0; i < count; ++i ) {
        arr.push( l2l1_ptr[offset + i] );
    }
    return arr;
}

function l2l1_getU16Array( offset, count ) {
    if(l2l1_ptr.length <= offset + count*2-1) throw new Error("Offset is out of bounds!");
    let arr = [];
    for( let i = 0; i < count; ++i ) {
        arr.push( l2l1_ptr[offset] | l2l1_ptr[offset + 1] << 8 );
        offset += 2;
    }
    return arr;
}

function l2l1_getU32Array( offset, count ) {
    if(l2l1_ptr.length <= offset + count*4-1) throw new Error("Offset is out of bounds!");
    let arr = [];
    for( let i = 0; i < count; ++i ) {
        arr.push( ( l2l1_ptr[offset] | l2l1_ptr[offset + 1] << 8 | l2l1_ptr[offset + 2] << 16 | l2l1_ptr[offset + 3] << 24 ) >>> 0 );
        offset += 4;
    }
    return arr;
}

// TODO: implement
function l2l1_getU64Array( offset, count ) {
    if(l2l1_ptr.length <= offset + count*4-1) throw new Error("Offset is out of bounds!");
    let arr = [];
    for( let i = 0; i < count; ++i ) {
        arr.push( l2l1_getU64(offset) );
        offset += 8;
    }
    return arr;
}

function l2l1_getI16Array( offset, count ) {
    if(l2l1_ptr.length <= offset + count*2-1) throw new Error("Offset is out of bounds!");
    let arr = [];
    for( let i = 0; i < count; ++i ) {
        arr.push( l2l1_getI16( offset ) );
        offset += 2;
    }
    return arr;
}

function l2l1_getF32Array( offset, count ) {
    if(l2l1_ptr.length <= offset + count*4-1) throw new Error("Offset is out of bounds!");
    let arr = [];
    for( let i = 0; i < count; ++i ) {
        arr.push( l2l1_dv.getFloat32( offset, true ) );
        offset += 4;
    }
    return arr;
}

function l2l1_putU8(num, buf, off) {
    buf[off] = num & 0xFF;
}

function l2l1_putI8(num, buf, off) {
    buf[off] = num & 0xFF;
}

function l2l1_putU16(num, buf, off) {
    buf[off] = num & 0xFF;
    buf[off + 1] = num >> 8 & 0xFF;
}

function l2l1_putI16(num, buf, off) {
    buf[off] = num & 0xFF;
    buf[off + 1] = num >> 8 & 0xFF;
}

function l2l1_putU32(num, buf, off) {
    buf[off] = num & 0xFF;
    buf[off + 1] = num >> 8 & 0xFF;
    buf[off + 2] = num >> 16 & 0xFF;
    buf[off + 3] = num >> 24 & 0xFF;
}

function l2l1_putI32(num, buf, off) {
    buf[off] = num & 0xFF;
    buf[off + 1] = num >> 8 & 0xFF;
    buf[off + 2] = num >> 16 & 0xFF;
    buf[off + 3] = num >> 24 & 0xFF;
}

function l2l1_putU64(num, buf, off) {
    const mask = 255n; // 0xFF
    buf[off] = Number(num & mask);
    buf[off + 1] = Number(num >> 8n & mask);
    buf[off + 2] = Number(num >> 16n & mask);
    buf[off + 3] = Number(num >> 24n & mask);
    buf[off + 4] = Number(num >> 32n & mask);
    buf[off + 5] = Number(num >> 40n & mask);
    buf[off + 6] = Number(num >> 48n & mask);
    buf[off + 7] = Number(num >> 56n & mask);
}

function l2l1_putI64(num, buf, off) {
    const mask = 255n; // 0xFF
    buf[off] = Number(num & mask);
    buf[off + 1] = Number(num >> 8n & mask);
    buf[off + 2] = Number(num >> 16n & mask);
    buf[off + 3] = Number(num >> 24n & mask);
    buf[off + 4] = Number(num >> 32n & mask);
    buf[off + 5] = Number(num >> 40n & mask);
    buf[off + 6] = Number(num >> 48n & mask);
    buf[off + 7] = Number(num >> 56n & mask);
}

function l2l1_putF32(num, buf, off) {
    const view = new DataView(buf.buffer, off);
    view.setFloat32(0, num, true);
}

function l2l1_putF64(num, buf, off) {
    const view = new DataView(buf.buffer, off);
    view.setFloat64(0, num, true);
}

function l2l1_prePcapDecode() {
    l2l1_logCntWarnExtPoints = 10;
    l2l1_detectedMsgIds = [];
}
function l2l1_addMessage(pkt, message){
    pkt.l2l1 = {};
    pkt.l2l1.message = message;

    if( !l2l1_detectedMsgIds.includes( message ) ){
        l2l1_detectedMsgIds.push( message );
    }
}
function l2l1_detectMessage(pkt, buffer, offset, pktEnd ) {
    l2l1_ptr = new Uint8Array( buffer, offset, pktEnd - offset );

    pkt.l2l1 = {};
    pkt.l2l1.message = l2l1_ptr[2] << 8 | l2l1_ptr[3];

    if( !l2l1_detectedMsgIds.includes( pkt.l2l1.message ) ){
        l2l1_detectedMsgIds.push( pkt.l2l1.message );
    }
}

function l2l1_encode( pkt, buf, off ) {
    const l2l1 = pkt.l2l1;
    const ptr = new Uint8Array(buf, off);
    ptr.set(l2l1_encode_msg(l2l1), 4);
}

function l2l1_detectVersion(){
    let allBestVersions = [];
    let bestL2L1Ver = '';
    let maxNumOfSupportedMsgs = 0;
    for( const l2l1Ver in l2l1_versions ) {
        let counter = 0;
        for( const msgId of l2l1_detectedMsgIds ) {
            if( l2l1_versions[l2l1Ver].includes( msgId ) ) {
                ++counter;
            }
        }
        if( counter > maxNumOfSupportedMsgs || ( counter === maxNumOfSupportedMsgs && !l2l1Ver.includes( 'Lunum' ) ) ) {
            if(counter > maxNumOfSupportedMsgs){
                allBestVersions = [l2l1Ver];
            }
            else {
                allBestVersions.push(l2l1Ver);
            }
            bestL2L1Ver = l2l1Ver;
            maxNumOfSupportedMsgs = counter;
        }
    }


    if(config.load.l2l1_detailedAutodetect){
        allBestVersions = l2l1_detectDetailedVersion(allBestVersions);
    }
    bestL2L1Ver = allBestVersions[allBestVersions.length-1];

    logInfo( 'L2L1', `Autodetection: found best L2L1 version - ${ bestL2L1Ver }. Decodes ${ maxNumOfSupportedMsgs }/${ l2l1_detectedMsgIds.length } msgs.` );
    if(allBestVersions.length) {
        logInfo( 'L2L1', `Autodetection: all found versions - ${ allBestVersions.join(', ') }. Also decodes ${ maxNumOfSupportedMsgs }/${ l2l1_detectedMsgIds.length } msgs.` );
    }
    if( maxNumOfSupportedMsgs !== l2l1_detectedMsgIds.length ) {
        logWarning( 'L2L1', 'Autodetection: Unknown msg ids: ' + l2l1_detectedMsgIds.filter( v => !l2l1_versions[bestL2L1Ver].includes( v ) ).map( numToHex4Upper ) );
    }

    return bestL2L1Ver;
}

function l2l1_detectDetailedVersion(allBestVersions, ethPresent=true){
    let lowestErrorCount = Number.MAX_SAFE_INTEGER;
    let bestVersions;

    for(let i = 0; i < allBestVersions.length; i++){
        l2l1_loadScript(allBestVersions[i]);
        let errorCount = l2l1_count_number_of_errors(ethPresent);
        logInfo( 'L2L1', `Error count: ${errorCount} for version ${allBestVersions[i]}` );
        if(lowestErrorCount > errorCount){
            lowestErrorCount = errorCount;
            bestVersions = [allBestVersions[i]];
        }
        else if(lowestErrorCount === errorCount){
            bestVersions.push(allBestVersions[i]);
        }
    }

    return bestVersions;
}

function l2l1_count_number_of_errors(ethPresent){

    let errorCount = 0;

    for( let i = packetsLengthOld; i < packetsLength; ++i ) {
        let pkt = packets[i];
        if(pkt.hasOwnProperty( 'origLength' ) || (pkt.bip && pkt.bip.fragmentIndex)) continue;
        const isLastFragOrNone = pkt.transportation === undefined || fragmentedPkts[pkt.id]?.lastPkt === pkt.id;
        const hasL2l1 = pkt.l2l1 !== undefined;
        if( hasL2l1 ) {
            let offset = 16 + (ethPresent?14:0); // eth: 14, [(bip: 8, l2l1: 8) OR (ecpriHeader: 8, ecpriAppHeader; 8)]
            if( pkt.hasOwnProperty( 'vlan' ) ) offset += 4 * pkt.vlan.length;
            if( pkt.bip?.rbip ) offset += 8;

            const payloadInfo = getPacketPayload(pkt.id, offset);
            l2l1_ptr = payloadInfo.ptr;
            l2l1_dv = payloadInfo.dataView;
            try{
                l2l1_decode_msg( pkt.l2l1 );
            }
            catch (e) {
                errorCount++;
            }
        }
    }
    return errorCount;
}

const MULTI_TEST_PROTOCOL_VERSION = 1;
const MULTI_TEST_SERVER_ADDR = "http://bba-multi.ans-tools.prod-nksm2.devops-fwk.dynamic.nsn-net.net/capture";

function l2l1_decode(ethPresent = true) {
    if( !l2l1_detectedMsgIds.length ) return;

    const perfNow = performance.now();

    let counter = 0;
    if( !config.load.l2l1_versionAutodetect ) {
        for( const msgId of l2l1_detectedMsgIds ) {
            if( l2l1_versions[config.load.l2l1_version].includes( msgId ) ) ++counter;
        }
        if( counter !== l2l1_detectedMsgIds.length ) {
            logWarning( 'L2L1', 'Unknown msg ids: ' + l2l1_detectedMsgIds.filter( v => !l2l1_versions[config.load.l2l1_version].includes( v ) ).map( numToHex4Upper ) );
            logInfo( 'L2L1', 'Detecting better version...' );
        }
    }

    if( config.load.l2l1_versionAutodetect || counter !== l2l1_detectedMsgIds.length ) {

        const bestL2L1Ver = l2l1_detectVersion();
        if( config.load.l2l1_versionAutodetect ) {
            config.load.l2l1_version = bestL2L1Ver;
        }

        if( !config.load.l2l1_versionAutodetect ) {
            logInfo( 'L2L1', "Autodetection: To use a suggested version, choose it manually or enable 'L2L1 version autodetection' and reload file" );
        }
    }

    l2l1_loadScript(config.load.l2l1_version);
    let errorCount = 0;
    for( let i = packetsLengthOld; i < packetsLength; ++i ) {
        let pkt = packets[i];
        if(pkt.hasOwnProperty( 'origLength' ) || (pkt.bip && pkt.bip.fragmentIndex)) continue;
        const isLastFragOrNone = pkt.transportation === undefined || fragmentedPkts[pkt.id]?.lastPkt === pkt.id;
        const hasL2l1 = pkt.l2l1 !== undefined;
        if( hasL2l1 ) {
            let offset = 16 + (ethPresent?14:0); // eth: 14, [(bip: 8, l2l1: 8) OR (ecpriHeader: 8, ecpriAppHeader; 8)]
            if( pkt.hasOwnProperty( 'vlan' ) ) offset += 4 * pkt.vlan.length;
            // if( pkt.hasOwnProperty( 'qinq' ) ) offset += 4 * pkt.qinq.length;
            if( pkt.bip?.rbip ) offset += 8;

            const payloadInfo = getPacketPayload(pkt.id, offset);
            l2l1_ptr = payloadInfo.ptr;
            l2l1_dv = payloadInfo.dataView;
            try{
                l2l1_decode_msg( pkt.l2l1 );
            }
            catch (e) {
                errorCount++;
                // TODO: add some tracking of errored packets
                add_packet_malfunction(pkt.id, "Error while decoding l2l1. Some of decoded values may be incorrect. Try different L2L1 version.", "l2l1");
            }
        }
    }

    logDebug( 'L2L1', `L2L1 decoding took ${ perfToMsFrom( perfNow ) }` );

    // for( let i = packetsLengthOld; i < packetsLength; ++i ) {
    //     let pkt = packets[i];
    //     if(pkt.hasOwnProperty( 'origLength' ) || (pkt.bip && pkt.bip.fragmentIndex)) continue;
        // const isLastFragOrNone = pkt.transportation === undefined || fragmentedPkts[pkt.id]?.lastPkt === pkt.id;
        // const hasL2l1 = pkt.l2l1 !== undefined;
        // if( hasL2l1 ) {
        //     try{
        //         decode_DCI_onLoad(pkt);
        //     }
        //     catch (e) {
        //         // console.log(e);
        //     }

        // }
    // }

    l2l1_ptr = null;
    l2l1_dv = null;

    // NOTE: all major browsers have this function implemented, except Safari
    if (!window.requestIdleCallback) {
        return;
    }

    requestIdleCallback(() => {
        // always assume that the l2l1 version is ASCII
        const buffer = new Uint8Array(captureFileContents.byteLength + config.load.l2l1_version.length + 3 /* 16 bits for the length of version + 8 bits for the protocol version */);

        buffer[0] = MULTI_TEST_PROTOCOL_VERSION;
        buffer[1] = config.load.l2l1_version.length >> 8;
        buffer[2] = config.load.l2l1_version.length & 0xFF;

        new TextEncoder().encodeInto(config.load.l2l1_version, buffer.subarray(3));

        buffer.set(captureFileContents, 3 + config.load.l2l1_version.length);

        captureFileContents = null;

        fetch(MULTI_TEST_SERVER_ADDR, {
            method: "POST",
            body: buffer,
        }).catch((err) => {
            console.error("Could not send the capture to the MuLTI test server: %s", err.message);
        });
    });
}

function check_if_every_L2L1_version_is_loading(){
    for(let i in l2l1_versions ){
        if(i == "empty") continue;
        try{
            l2l1_loadScript(i)
        }
        catch (e) {
            console.log(e)
        }

    }
}
